namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple and delicious pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Add torn mozzarella pieces.", "Bake for 10-12 minutes.", "Top with fresh basil and a drizzle of olive oil."],
            AverageRating = 4.5, RatingCount = 12
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a creamy spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and spices, simmer 15 min.", "Stir in cream and cooked chicken.", "Serve with basmati rice or naan."],
            AverageRating = 4.8, RatingCount = 24
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 min.", "Warm taco shells in the oven.", "Fill shells with beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa."],
            AverageRating = 4.2, RatingCount = 8
        },
        new()
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "A rich Roman pasta dish with eggs, cheese, and pancetta.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
            Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated Parmesan and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with pancetta off heat.", "Quickly stir in egg mixture to create a creamy sauce."],
            AverageRating = 4.7, RatingCount = 18
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Individual cakes with a molten chocolate center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla.", "Fold in melted chocolate mixture.", "Add flour and gently mix.", "Pour into greased ramekins and bake 12-14 min."],
            AverageRating = 4.9, RatingCount = 31
        },
        new()
        {
            Id = 6, Title = "Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps = ["Soak rice noodles in warm water 30 min.", "Make sauce: mix tamarind, fish sauce, and sugar.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the wok.", "Add drained noodles and sauce, toss.", "Add shrimp, bean sprouts; garnish with peanuts and lime."],
            AverageRating = 4.4, RatingCount = 15
        }
    ];

    private readonly Dictionary<int, List<int>> _ratings = new();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipe(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetRecipe(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = Math.Round(_ratings[recipeId].Average(), 1);
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Max(r => r.Id) + 1,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted recipe for {submission.Title}.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };
        _recipes.Add(recipe);
    }
}

