    [Parameter] public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe "@submission.Title" has been submitted successfully.
    </div>
    <a href="/" class="btn btn-primary">← Back to Home</a>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
