                @foreach (var ingredient in recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>
        <div class="col-md-8">
            <h3>Steps</h3>
            <ol class="list-group list-group-numbered">
                @foreach (var step in recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <a href="/category/@recipe.Category" class="btn btn-secondary mt-4">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private RecipeHub.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe "@submission.Title" has been submitted successfully.
    </div>
    <a href="/" class="btn btn-primary">← Back to Home</a>
}
else
{
    <div class="row">
        <div class="col-md-8">
            <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
                <div class="mb-3">
                    <label class="form-label" for="title">Recipe Title</label>
                    <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="category">Category</label>
                    <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
                        <option value="">-- Select a category --</option>
                        <option value="Italian">Italian</option>
                        <option value="Indian">Indian</option>
                        <option value="Mexican">Mexican</option>
                        <option value="Asian">Asian</option>
                        <option value="Desserts">Desserts</option>
                        <option value="American">American</option>
                        <option value="Other">Other</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label class="form-label" for="ingredients">Ingredients (one per line)</label>
                    <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="submission.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="steps">Steps (one per line)</label>
                    <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="submission.Steps" placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
                </div>

                <button type="submit" class="btn btn-success" disabled="@(!IsValid)">Submit Recipe</button>
                <a href="/" class="btn btn-secondary ms-2">Cancel</a>
            </EditForm>
        </div>
    </div>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(submission.Title) &&
        !string.IsNullOrWhiteSpace(submission.Category) &&
        !string.IsNullOrWhiteSpace(submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(submission.Steps);

    private void HandleSubmit()
    {
        if (!IsValid) return;
        RecipeService.SubmitRecipe(submission);
        submitted = true;
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="my-3 p-3 border rounded">
    <div class="d-flex align-items-center gap-2">
        <span class="fw-bold">Rate this recipe:</span>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-4 text-decoration-none"
                    @onclick="() => Rate(star)"
                    title="Rate @star stars">
                @(star <= (hoverRating > 0 ? hoverRating : userRating) ? "★" : "☆")
            </button>
        }
        @if (userRating > 0)
        {
            <span class="text-success ms-2">You rated @userRating/5!</span>
        }
    </div>
    <small class="text-muted">
        Community average: @CurrentRating / 5 (@RatingCount ratings)
    </small>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int userRating;
    private int hoverRating;

    private void Rate(int stars)
    {
        userRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

